/**
 * Image data for the whole site.
 * Reads the manifest generated by `npm run images`. import.meta.glob is used instead of a
 * normal import so the site still builds (showing empty states) before the manifest exists.
 */
const manifestModules = import.meta.glob('./images.generated.json', { eager: true, import: 'default' });
const manifest = manifestModules['./images.generated.json'] ?? { images: [] };

export const heroImages = manifest.images.filter((image) => image.use === 'hero');
export const galleryImages = manifest.images.filter((image) => image.use === 'gallery');
export const aboutImage = manifest.images.find((image) => image.use === 'about') ?? null;

export const GALLERY_CATEGORIES = [
  { id: 'all', label: 'All' },
  { id: 'wedding', label: 'Wedding' },
  { id: 'portrait', label: 'Portrait' },
  { id: 'travel', label: 'Travel' },
  { id: 'street', label: 'Street' },
];
